//! Re-admit the canonical terminal AAC edit generated by transport conversion.
use super::{assert_no_tools, converter};
use crate::{
    concurrency::Stop,
    conversion::{
        ContentKey, ConversionRequest, Converter, HlsInputKeys, InputKeys, OutputKey,
        ProcessingMode, VerificationRequest, VerificationSource,
        audio_presentation::{self, AudioClaim, AudioEvidence, AudioPresentation},
        native::{SegmentedMedia, tests},
        native_media::SegmentTransformer,
    },
    inspection::{OutputFormat, TargetProtection},
};
use std::{fmt::Write, path::PathBuf};

const KID: &str = "00112233445566778899aabbccddeeff";
const KEY: &str = "ffeeddccbbaa99887766554433221100";

struct Fixture {
    owner: crate::conversion::files::Stage,
    initialization: PathBuf,
    resources: Vec<PathBuf>,
    expected: AudioPresentation,
}
impl Fixture {
    fn new(converter: &Converter) -> Self {
        let owner = crate::conversion::files::Stage::new(None).unwrap();
        let source = tests::short_audio_transport(owner.path());
        let stop = Stop::new();
        let mut scanner = crate::conversion::ts::NativeScanner::new();
        scanner.segment(&source, &stop).unwrap();
        let (_, anchors) = scanner.finish().unwrap();
        let anchor = anchors.values().next().unwrap();
        let full = owner.path().join("audio.mp4");
        converter
            .backend
            .demux_transport(
                &source,
                crate::inspection::TrackKind::Audio,
                &full,
                Some(anchor),
            )
            .unwrap();
        let timing = anchor.timing().unwrap();
        let expected = AudioPresentation::new(
            AudioEvidence {
                sample_rate: 44_100,
                coded_frames: timing.count,
                raw_first_pts: timing.first_pts,
                raw_coded_end: timing.end_pts,
            },
            timing.count * 1024 - 17,
        )
        .unwrap();
        assert!(expected.evidence.raw_first_pts > 0);
        audio_presentation::restore(&full, expected, &stop).unwrap();
        let bytes = std::fs::read(&full).unwrap();
        let (init, fragments) = crate::mp4::split_fragmented(&bytes).unwrap();
        let initialization = owner.path().join("init.mp4");
        std::fs::write(&initialization, init).unwrap();
        let resources = fragments
            .iter()
            .enumerate()
            .map(|(index, fragment)| {
                let resource = owner.path().join(format!("part-{index}.m4s"));
                std::fs::write(&resource, fragment).unwrap();
                resource
            })
            .collect();
        Self {
            owner,
            initialization,
            resources,
            expected,
        }
    }
    fn admit(
        &self,
        converter: &Converter,
    ) -> Result<SegmentedMedia, crate::conversion::ConversionError> {
        converter.backend.native_manifest_segmented_media(
            &self.initialization,
            &self.resources,
            &InputKeys::default(),
        )
    }
}

#[test]
fn a_generated_terminal_audio_edit_is_valid_segmented_input() {
    let (converter, events) = converter();
    let fixture = Fixture::new(&converter);
    let admitted = fixture.admit(&converter).unwrap();
    assert_eq!(
        admitted.media.tracks[0].samples.count,
        fixture.expected.evidence.coded_frames
    );
    assert_eq!(admitted.audio_presentation, Some(fixture.expected));
    assert!(
        converter
            .backend
            .native_admit_segmented(&admitted)
            .unwrap()
            .passed
    );
    let mut initialization = fixture.initialization.clone();
    let mut resources = fixture.resources.clone();
    let mut keys = InputKeys::default();
    let key = OutputKey::from_hex(KID, KEY).unwrap();
    for target in [
        TargetProtection::Cenc,
        TargetProtection::Cbcs,
        TargetProtection::Clear,
    ] {
        let directory = fixture.owner.path().join(target.as_str());
        crate::native::create_media_dir_all(&directory).unwrap();
        let output_init = directory.join("init.mp4");
        let writer = SegmentTransformer::new(
            &initialization,
            &output_init,
            target,
            Some(&key),
            &Stop::new(),
        )
        .unwrap();
        let output_resources = resources
            .iter()
            .enumerate()
            .map(|(index, resource)| {
                let output = directory.join(format!("part-{index}.m4s"));
                writer
                    .rewrite_segment(resource, &output, &keys, &Stop::new())
                    .unwrap();
                output
            })
            .collect::<Vec<_>>();
        keys = if target == TargetProtection::Clear {
            InputKeys::default()
        } else {
            InputKeys::new(vec![ContentKey::from_hex(KID, KEY).unwrap()]).unwrap()
        };
        let output = converter
            .backend
            .native_manifest_segmented_media(&output_init, &output_resources, &keys)
            .unwrap();
        assert_eq!(output.audio_presentation, Some(fixture.expected));
        assert!(
            converter
                .backend
                .native_verify_segmented(&admitted, &output)
                .unwrap()
                .passed
        );
        initialization = output_init;
        resources = output_resources;
    }
    assert_no_tools(&events);
}

fn edit_payload(bytes: &[u8]) -> usize {
    let boxes = crate::mp4::parse_boxes(bytes).unwrap();
    let edit = crate::mp4::walk(&boxes)
        .into_iter()
        .find(|node| node.kind() == *b"elst")
        .unwrap();
    edit.header.offset + edit.header.header_size
}
fn changed_word(bytes: &[u8], at: usize, change: i64) -> Vec<u8> {
    let mut changed = bytes.to_vec();
    let old = u64::from_be_bytes(bytes[at..at + 8].try_into().unwrap());
    changed[at..at + 8].copy_from_slice(&old.checked_add_signed(change).unwrap().to_be_bytes());
    changed
}
#[test]
fn canonical_audio_edits_require_exact_origins_and_bind_the_terminal_sample_selection() {
    let (converter, events) = converter();
    let fixture = Fixture::new(&converter);
    let admitted = fixture.admit(&converter).unwrap();
    let original = std::fs::read(&fixture.initialization).unwrap();
    let at = edit_payload(&original);
    for changed in [
        changed_word(&original, at + 8, 1),
        changed_word(&original, at + 36, 1),
        changed_word(&original, at + 28, -102_400),
    ] {
        std::fs::write(&fixture.initialization, changed).unwrap();
        assert!(fixture.admit(&converter).is_err());
    }
    // One sample is a valid different range, so admission succeeds but comparison must fail.
    std::fs::write(
        &fixture.initialization,
        changed_word(&original, at + 28, -100),
    )
    .unwrap();
    let changed = fixture.admit(&converter).unwrap();
    let compared = converter
        .backend
        .native_verify_segmented(&admitted, &changed)
        .unwrap();
    assert!(!compared.passed && !compared.checks.packet_timing_equal);
    assert!(compared.checks.packet_payloads_equal && compared.checks.stream_metadata.is_pass());
    std::fs::write(&fixture.initialization, original).unwrap();
    assert_eq!(
        fixture.admit(&converter).unwrap().audio_presentation,
        Some(fixture.expected)
    );
    assert_no_tools(&events);
}

fn cbcs_dash(fixture: &Fixture, converter: &Converter) -> PathBuf {
    let directory = fixture.owner.path().join("cbcs-dash");
    crate::native::create_media_dir_all(&directory).unwrap();
    let initialization = directory.join("init.mp4");
    let key = OutputKey::from_hex(KID, KEY).unwrap();
    let transformer = SegmentTransformer::new(
        &fixture.initialization,
        &initialization,
        TargetProtection::Cbcs,
        Some(&key),
        &Stop::new(),
    )
    .unwrap();
    let mut clock =
        crate::conversion::timing::FragmentClock::read(&fixture.initialization).unwrap();
    let mut timeline = String::new();
    let mut references = String::new();
    for (index, resource) in fixture.resources.iter().enumerate() {
        let name = format!("part-{index}.m4s");
        transformer
            .rewrite_segment(
                resource,
                &directory.join(&name),
                &InputKeys::default(),
                &Stop::new(),
            )
            .unwrap();
        let (first, duration, scale) = clock.dash_segment(resource).unwrap();
        assert_eq!(scale, 90_000);
        write!(
            timeline,
            "<S t=\"{}\" d=\"{}\"/>",
            first * 49,
            duration * 49
        )
        .unwrap();
        write!(references, "<SegmentURL media=\"{name}\"/>").unwrap();
    }
    let source = directory.join("manifest.mpd");
    let origin = u64::try_from(fixture.expected.evidence.raw_first_pts).unwrap() * 49;
    let duration = fixture.expected.presented_samples * 100;
    let period =
        audio_presentation::seconds(u128::from(fixture.expected.presented_samples), 44_100)
            .unwrap();
    std::fs::write(&source, format!(
        "<MPD xmlns=\"urn:mpeg:dash:schema:mpd:2011\" xmlns:cenc=\"urn:mpeg:cenc:2013\" type=\"static\"><Period duration=\"PT{period}S\"><AdaptationSet contentType=\"audio\"><ContentProtection schemeIdUri=\"urn:mpeg:dash:mp4protection:2011\" value=\"cbcs\" cenc:default_KID=\"00112233-4455-6677-8899-aabbccddeeff\"/><Representation id=\"audio\" bandwidth=\"128000\" codecs=\"mp4a.40.2\" mimeType=\"audio/mp4\" audioSamplingRate=\"44100\"><SegmentList timescale=\"4410000\" presentationTimeOffset=\"{origin}\" presentationDuration=\"{duration}\"><Initialization sourceURL=\"init.mp4\"/><SegmentTimeline>{timeline}</SegmentTimeline>{references}</SegmentList></Representation></AdaptationSet></Period></MPD>"
    )).unwrap();
    let keys = InputKeys::new(vec![ContentKey::from_hex(KID, KEY).unwrap()]).unwrap();
    converter
        .backend
        .native_manifest_segmented_media(
            &initialization,
            &std::fs::read_dir(&directory)
                .unwrap()
                .map(|entry| entry.unwrap().path())
                .filter(|path| path.extension().is_some_and(|ext| ext == "m4s"))
                .collect::<Vec<_>>(),
            &keys,
        )
        .unwrap();
    source
}

#[test]
fn native_cbcs_dash_to_clear_hls_clips_the_last_aac_frame_and_reverifies() {
    let (converter, events) = converter();
    let converter = converter.with_processing(ProcessingMode::Segments);
    let fixture = Fixture::new(&converter);
    let source = cbcs_dash(&fixture, &converter);
    let destination = fixture.owner.path().join("clear-hls");
    let keys = InputKeys::new(vec![ContentKey::from_hex(KID, KEY).unwrap()]).unwrap();
    let hls = HlsInputKeys::default();
    let report = converter
        .convert(ConversionRequest {
            input: &source,
            output: &destination,
            format: OutputFormat::Hls,
            target: TargetProtection::Clear,
            input_keys: &keys,
            hls_input_keys: &hls,
            output_key: None,
            hls_key_uri: None,
            hls_output_key: None,
        })
        .unwrap();
    assert!(report.verification.passed);
    let output = destination.join("master.m3u8");
    let verified = converter
        .verify(VerificationRequest {
            source: VerificationSource {
                input: &source,
                input_keys: &keys,
                hls_keys: &hls,
            },
            output: VerificationSource {
                input: &output,
                input_keys: &InputKeys::default(),
                hls_keys: &hls,
            },
        })
        .unwrap();
    assert!(verified.passed);
    assert_no_tools(&events);
}

#[test]
fn long_audio_range_uses_the_visible_end_and_carries_nanosecond_rounding() {
    let claim = AudioClaim {
        sample_rate: 44_100,
        raw_first_pts: 900_000,
        presented_samples: 26_306_800,
    };
    let (first, end, scale) = claim.interval(54_361_159, 54_588_946).unwrap();
    assert_eq!((end - first, scale), (11_083_209, 4_410_000));
    assert_eq!(
        audio_presentation::seconds(u128::from(end - first), u128::from(scale)).unwrap(),
        "2.51319932"
    );
    assert_eq!(
        crate::conversion::finite::manifest::seconds(227_787, 90_000).unwrap(),
        "2.530966667"
    );
    assert_eq!(
        audio_presentation::seconds(9_999_999_999, 10_000_000_000).unwrap(),
        "1"
    );
    assert!(
        audio_presentation::declaration_matches("0.999999999", 9_999_999_999, 10_000_000_000)
            .is_err()
    );
}
